insert into public.diretorio_salas (nome,num,nome_en,nome_pt,descricao_en,descricao_pt,raridade_en,raridade_pt,custo_en,custo_pt,tipo_en,tipo_pt,categorias,diretorio,imagem,fonte,atualizado_em) values
('The Pool',29,'The Pool','The Pool','An indoor Orindian pool was one of the more modern additions to the estate, the inclusion of which provided a convenient excuse for building a handful of other rooms which not only complement an indoor pool, but are often compulsory inclusions.','Uma piscina coberta de estilo orindiano foi uma das adições mais modernas à propriedade, cuja inclusão serviu de pretexto conveniente para construir um punhado de outros cômodos que não só complementam uma piscina interna, mas muitas vezes são inclusões obrigatórias.','Standard','Padrão','1 gem','1 gema','Drafting, Blueprint','Sorteio (Drafting), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 025-036','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20025-036/The%20Pool.png','https://blueprince.wiki.gg/wiki/The_Pool',now()),
('Drafting Studio',30,'Drafting Studio','Drafting Studio','As an architect and engineer, it was not uncommon to find your great uncle spending the better part of his weekends here, at a drafting table with t-square and compass in hand. Over half of the floorplans of Mt. Holly were conceptualized, refined and drafted in this studio.','Como arquiteto e engenheiro, não era incomum encontrar seu tio-avô passando boa parte de seus fins de semana aqui, numa prancheta de desenho com esquadro e compasso em mãos. Mais da metade das plantas de Mt. Holly foram concebidas, refinadas e desenhadas neste estúdio.','Rare','Raro','2 gems','2 gemas','Drafting, Blueprint','Sorteio (Drafting), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 025-036','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20025-036/Drafting%20Studio.png','https://blueprince.wiki.gg/wiki/Drafting_Studio',now()),
('Utility Closet',31,'Utility Closet','Utility Closet','One benefit of the restoration of old buildings is that it allows the owners to update and add modern amenities. The utility closet and the circuit breaker box within were set up when gas powered lighting was retired and replaced by a more fashionable home electrical system.','Um benefício da restauração de prédios antigos é permitir que os proprietários atualizem e acrescentem comodidades modernas. O armário de utilidades e o quadro de disjuntores em seu interior foram instalados quando a iluminação a gás foi aposentada e substituída por um sistema elétrico residencial mais moderno.','Standard','Padrão','0 gems','0 gemas','Mechanical, Blueprint, Dead End','Mecânico (Mechanical), Blueprint (planta azul), Beco sem saída (Dead End)',ARRAY['Blueprint']::text[],'Rooms 025-036','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20025-036/Utility%20Closet.png','https://blueprince.wiki.gg/wiki/Utility_Closet',now()),
('Boiler Room',32,'Boiler Room','Boiler Room','A utility room serving as a central hub for controlling the heating and steam power supplied to various rooms of the estate. Steam power is conveyed in the estate through steam ducts that run through select rooms. These floorplans must be drafted in an alignment that will facilitate the steam traveling through the house to reach its intended destination.','Uma sala de utilidades que serve de central para o controle do aquecimento e da energia a vapor fornecidos a vários cômodos da propriedade. A energia a vapor é conduzida na propriedade por dutos de vapor que passam por cômodos selecionados. Essas plantas precisam ser posicionadas de forma a facilitar a passagem do vapor pela casa até chegar ao destino pretendido.','Unusual','Incomum','1 gem','1 gema','Mechanical, Blueprint','Mecânico (Mechanical), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 025-036','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20025-036/Boiler%20Room.png','https://blueprince.wiki.gg/wiki/Boiler_Room',now()),
('Pump Room',33,'Pump Room','Pump Room','This facility, dedicated to the filtration and flow of water throughout the estate, houses five water pumps and three oversized tanks. The Pump Room can be utilized for a number of maintenance tasks, from draining the pool to activating the sprinkler system.','Esta instalação, dedicada à filtragem e ao fluxo de água por toda a propriedade, abriga cinco bombas de água e três tanques superdimensionados. A Casa de Bombas pode ser usada para uma série de tarefas de manutenção, desde esvaziar a piscina até acionar o sistema de aspersores.','Unusual','Incomum','0 gems','0 gemas','Mechanical, Blueprint, Addition','Mecânico (Mechanical), Blueprint (planta azul), Adição (Addition)',ARRAY['Blueprint']::text[],'Rooms 025-036','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20025-036/Pump%20Room.png','https://blueprince.wiki.gg/wiki/Pump_Room',now()),
('Security',34,'Security','Security','A control room with state of the art surveillance equipment, inventory system, and access control via an electronic computer terminal. This room is where the estate''s patrol guards kick up their feet and thank their stars they are living in modern era.','Uma sala de controle com equipamento de vigilância de última geração, sistema de inventário e controle de acesso por um terminal de computador eletrônico. É neste cômodo que os guardas de patrulha da propriedade descansam os pés e agradecem por viver na era moderna.','Standard','Padrão','1 gem','1 gema','Mechanical, Blueprint','Mecânico (Mechanical), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 025-036','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20025-036/Security.png','https://blueprince.wiki.gg/wiki/Security',now()),
('Workshop',35,'Workshop','Workshop','Springs, screws and coils scattered atop the workbench show signs of this room''s frequent use. A craftsman''s studio dedicated to creativity and invention, this room was used by your uncle regularly whenever he needed to fix (or improve) a gadget or contraption.','Molas, parafusos e bobinas espalhados sobre a bancada mostram sinais do uso frequente deste cômodo. Um ateliê de artesão dedicado à criatividade e à invenção, este cômodo era usado regularmente por seu tio sempre que precisava consertar (ou aperfeiçoar) algum aparelho ou engenhoca.','Unusual','Incomum','0 gems','0 gemas','Mechanical, Blueprint','Mecânico (Mechanical), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 025-036','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20025-036/Workshop.png','https://blueprince.wiki.gg/wiki/Workshop',now()),
('Laboratory',36,'Laboratory','Laboratory','A fully staffed research facility furnished with all manner of scientific equipment and measurement devices. This home laboratory provides a controlled environment in a remote location, far from prying eyes and traditional safety regulations.','Uma instalação de pesquisa totalmente equipada, provida de todo tipo de equipamento científico e instrumentos de medição. Este laboratório doméstico oferece um ambiente controlado em local remoto, longe de olhares curiosos e das normas de segurança tradicionais.','Standard','Padrão','1 gem','1 gema','Mechanical, Blueprint','Mecânico (Mechanical), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 025-036','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20025-036/Laboratory.png','https://blueprince.wiki.gg/wiki/Laboratory',now()),
('Sauna',37,'Sauna','Sauna','A traditional wood-lined Corarican style sauna, temperature controlled and exceptionally relaxing. The invigorating effects of this room will leave you waking up the next day feeling rejuvenated.','Uma sauna tradicional de estilo corárico, revestida de madeira, com temperatura controlada e excepcionalmente relaxante. Os efeitos revigorantes deste cômodo farão você acordar no dia seguinte se sentindo rejuvenescido.','Unusual','Incomum','0 gems','0 gemas','Tomorrow, Blueprint, Dead End, Addition','Tomorrow, Blueprint (planta azul), Beco sem saída (Dead End), Adição (Addition)',ARRAY['Blueprint']::text[],'Rooms 037-046','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20037-046/Sauna.png','https://blueprince.wiki.gg/wiki/Sauna',now()),
('Coat Check',38,'Coat Check','Coat Check','A cloakroom where guests may leave their coats, bags or hats in exchange for a claim ticket. This floor plan was usually drafted adjoining the Entrance Hall during larger social events such as a ball or gala.','Um chapelaria onde os hóspedes podem deixar seus casacos, bolsas ou chapéus em troca de uma ficha. Esta planta costumava ser posicionada junto ao Hall de Entrada durante grandes eventos sociais, como um baile ou uma gala.','Standard','Padrão','0 gems','0 gemas','Tomorrow, Blueprint, Dead End','Tomorrow, Blueprint (planta azul), Beco sem saída (Dead End)',ARRAY['Blueprint']::text[],'Rooms 037-046','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20037-046/Coat%20Check.png','https://blueprince.wiki.gg/wiki/Coat_Check',now()),
('Mail Room',39,'Mail Room','Mail Room','A dedicated mailing room in which incoming and outgoing post and packages are sorted and then delivered within the estate to their intended recipients.','Uma sala de correspondência dedicada, na qual a correspondência e as encomendas recebidas e enviadas são separadas e depois entregues dentro da propriedade aos seus respectivos destinatários.','Unusual','Incomum','0 gems','0 gemas','Tomorrow, Blueprint, Dead End','Tomorrow, Blueprint (planta azul), Beco sem saída (Dead End)',ARRAY['Blueprint']::text[],'Rooms 037-046','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20037-046/Mail%20Room.png','https://blueprince.wiki.gg/wiki/Mail_Room',now()),
('Freezer',40,'Freezer','Freezer','Dedicated to deep freeze and cold storage, Mt. Holly''s freezer is an insulated space kept almost as frigid as the snowy mountains of Corarica. Sustaining a subzero temperature is vital for keeping the items in this room under ice.','Dedicado ao congelamento profundo e ao armazenamento a frio, o Freezer de Mt. Holly é um espaço isolado mantido quase tão gélido quanto as montanhas nevadas de Corárica. Manter uma temperatura abaixo de zero é vital para conservar os itens deste cômodo sob o gelo.','Rare','Raro','0 gems','0 gemas','Tomorrow, Blueprint, Dead End','Tomorrow, Blueprint (planta azul), Beco sem saída (Dead End)',ARRAY['Blueprint']::text[],'Rooms 037-046','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20037-046/Freezer.png','https://blueprince.wiki.gg/wiki/Freezer',now()),
('Dining Room',41,'Dining Room','Dining Room','An intimate and warm room with a large dining table boasting a serving tray with a silver dome cover. Dinner is served here each evening.','Um cômodo íntimo e acolhedor com uma grande mesa de jantar exibindo uma bandeja de servir com tampa em cúpula de prata. O jantar é servido aqui todas as noites.','Standard','Padrão','0 gems','0 gemas','Blueprint','Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 037-046','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20037-046/Dining%20Room.png','https://blueprince.wiki.gg/wiki/Dining_Room',now()),
('Observatory',42,'Observatory','Observatory','Housing an impressively large telescope, Mount Holly''s observatory is a window to the world above and beyond the clouds and sky. Through its mirrored lens, even a novice stargazer will be able to distinctly appreciate the wonder, signs and constellations that punctuate the tapestry of night.','Abrigando um telescópio impressionantemente grande, o observatório de Mount Holly é uma janela para o mundo acima e além das nuvens e do céu. Através de sua lente espelhada, até um observador iniciante das estrelas conseguirá apreciar nitidamente as maravilhas, os sinais e as constelações que pontuam a tapeçaria da noite.','Standard','Padrão','1 gem','1 gema','Blueprint','Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 037-046','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20037-046/Observatory.png','https://blueprince.wiki.gg/wiki/Observatory',now()),
('Conference Room',43,'Conference Room','Conference Room','In his latter years, H. S. Sinclair had become withdrawn from public life and conducted all business from the comfort and privacy of home. This included the occasional board meetings which were held in the professional setting of this room.','Em seus últimos anos, H. S. Sinclair havia se afastado da vida pública e conduzia todos os negócios do conforto e da privacidade de casa. Isso incluía as ocasionais reuniões de diretoria, realizadas no ambiente profissional deste cômodo.','Unusual','Incomum','0 gems','0 gemas','Spread, Blueprint','Propagação (Spread), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 037-046','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20037-046/Conference%20Room.png','https://blueprince.wiki.gg/wiki/Conference_Room',now()),
('Aquarium',44,'Aquarium','Aquarium','In addition to having a bouquet of colorful fish swimming within them, each tank in the Aquarium is also inspired by the decor and colors of the various types of rooms found throughout the estate, including one or two red herrings.','Além de abrigarem um buquê de peixes coloridos nadando em seu interior, cada tanque do Aquário também se inspira na decoração e nas cores dos vários tipos de cômodos encontrados pela propriedade, incluindo um ou dois "peixes vermelhos" para despistar.','Unusual','Incomum','1 gem','1 gema','Red Room, Green Room, Hallway, Bedroom, Shop, Blackprint, Blueprint','Sala Vermelha (Red Room), Sala Verde (Green Room), Corredor (Hallway), Quarto (Bedroom), Loja (Shop), Blackprint (planta negra), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 037-046','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20037-046/Aquarium.png','https://blueprince.wiki.gg/wiki/Aquarium',now()),
('Antechamber',45,'Antechamber','Antechamber','From its root meaning "The Room Before", all signs and paths point toward the Antechamber. This mysterious sealed room - resting on the 9th Rank - may prove, however, quite an initial challenge to even reach, let alone enter. Still, you can''t help but draw a connection between this chamber and Room 46.','De seu significado original, "O Cômodo Anterior", todos os sinais e caminhos apontam para a Antecâmara. Este misterioso cômodo lacrado — situado na 9ª Fileira — pode, no entanto, ser um desafio e tanto até mesmo para alcançar, quanto mais para adentrar. Ainda assim, você não consegue deixar de traçar uma ligação entre esta câmara e o Cômodo 46.','n/a','n/d','None (no gem cost)','Nenhum (sem custo em gemas)','Blueprint, Objective','Blueprint (planta azul), Objetivo (Objective)',ARRAY['Blueprint']::text[],'Rooms 037-046','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20037-046/Antechamber.png','https://blueprince.wiki.gg/wiki/Antechamber',now()),
('Room 46',46,'Room 46','Room 46','The mysterious room mentioned in H. S. Sinclair''s will, named only by a number. Despite the house''s official blueprint only showing a total of 45 rooms, the words of the legal document make it apparent that a 46th room in the house in fact exists. Finding this room is your primary objective while on the estate. It is after all, your bequest.','O misterioso cômodo mencionado no testamento de H. S. Sinclair, nomeado apenas por um número. Embora a planta oficial da casa mostre um total de apenas 45 cômodos, as palavras do documento legal deixam claro que um 46º cômodo de fato existe na casa. Encontrar este cômodo é seu objetivo principal enquanto está na propriedade. Afinal, é a sua herança.','Rumored','Rumorejado','None (no gem cost)','Nenhum (sem custo em gemas)','Blueprint, Objective','Blueprint (planta azul), Objetivo (Objective)',ARRAY['Blueprint']::text[],'Rooms 037-046','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20037-046/Room%2046.png','https://blueprince.wiki.gg/wiki/Room_46',now()),
('Bedroom',47,'Bedroom','Bedroom','A familiar room that you may have slept in at some prior visit in the past. Like most bedrooms of the estate, these quarters offer you a little rest and recuperation during your long days exploring the surrounding rooms.','Um quarto familiar em que você talvez tenha dormido em alguma visita anterior no passado. Como a maioria dos quartos da propriedade, estes aposentos lhe oferecem um pouco de descanso e recuperação durante seus longos dias explorando os cômodos vizinhos.','Commonplace','Comum','None (no gem cost)','Nenhum (sem custo em gemas)','Entry, Bedroom','Entrada (Entry), Quarto (Bedroom)',ARRAY['Bedroom']::text[],'Bedrooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Bedrooms/Bedroom.png','https://blueprince.wiki.gg/wiki/Bedroom',now()),
('Boudoir',48,'Boudoir','Boudoir','A private salon with a plethora of fainting couches and chaise longues that served both as a dressing room for her Ladyship in the mornings and a cozy sitting room for her in the evenings.','Um salão privativo com uma profusão de divãs e chaises longues que servia tanto de vestiário para a Senhora pela manhã quanto de aconchegante sala de estar para ela à noite.','Standard','Padrão','None (no gem cost)','Nenhum (sem custo em gemas)','Bedroom','Quarto (Bedroom)',ARRAY['Bedroom']::text[],'Bedrooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Bedrooms/Boudoir.png','https://blueprince.wiki.gg/wiki/Boudoir',now()),
('Guest Bedroom',49,'Guest Bedroom','Guest Bedroom','A small bedroom maintained and kept available for accommodating weekend guests and impromptu visitors who find themselves compelled to stay the night.','Um pequeno quarto mantido disponível para acomodar hóspedes de fim de semana e visitantes de última hora que se veem compelidos a passar a noite.','Commonplace','Comum','None (no gem cost)','Nenhum (sem custo em gemas)','Bedroom, Dead End','Quarto (Bedroom), Beco sem saída (Dead End)',ARRAY['Bedroom']::text[],'Bedrooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Bedrooms/Guest%20Bedroom.png','https://blueprince.wiki.gg/wiki/Guest_Bedroom',now()),
('Nursery',50,'Nursery','Nursery','One of the few rooms you vividly remember from your visits here in your youth. Though even at that time, you remember feeling a little old for the activities provided here. The twin cribs found in this room might suggest that at one point in time there had been some hopeful expectations of a sudden growth of the family tree.','Um dos poucos cômodos que você lembra vividamente de suas visitas na infância. Ainda que, mesmo naquela época, você se lembre de se sentir um pouco velho demais para as atividades oferecidas aqui. Os berços gêmeos deste cômodo podem sugerir que, em algum momento, houve expectativas esperançosas de um súbito crescimento da árvore genealógica.','Commonplace','Comum','1 gem','1 gema','Drafting, Bedroom, Dead End','Sorteio (Drafting), Quarto (Bedroom), Beco sem saída (Dead End)',ARRAY['Bedroom']::text[],'Bedrooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Bedrooms/Nursery.png','https://blueprince.wiki.gg/wiki/Nursery',now()),
('Servant''s Quarters',51,'Servant''s Quarters','Servant''s Quarters','A cold empty room, devoid of ornamentation and personal effects. This suspiciously humble bedroom belonged to the Baron''s personal valet, Hartley Ruota, who had unchallenged access to even the most clandestine areas of the estate.','Um cômodo frio e vazio, desprovido de ornamentação e objetos pessoais. Este quarto suspeitamente humilde pertencia ao valete pessoal do Barão, Hartley Ruota, que tinha acesso irrestrito até às áreas mais clandestinas da propriedade.','Unusual','Incomum','1 gem','1 gema','Bedroom, Dead End','Quarto (Bedroom), Beco sem saída (Dead End)',ARRAY['Bedroom']::text[],'Bedrooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Bedrooms/Servant''s%20Quarters.png','https://blueprince.wiki.gg/wiki/Servant''s_Quarters',now()),
('Bunk Room',52,'Bunk Room','Bunk Room','The rustic, wooden stacked bunk beds evoke the enticing promise of campfire stories and childhood adventures. This bedroom served as a pillowfort and bedroom to the young Sinclair boys, and has remained faithfully unchanged over the years.','As rústicas beliches de madeira empilhadas evocam a promessa sedutora de histórias ao redor da fogueira e aventuras de infância. Este quarto serviu de forte de travesseiros e dormitório para os jovens meninos Sinclair, e permaneceu fielmente inalterado ao longo dos anos.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Bedroom, Bedroom, Dead End, Dead End','Quarto (Bedroom), Quarto (Bedroom), Beco sem saída (Dead End), Beco sem saída (Dead End)',ARRAY['Bedroom']::text[],'Bedrooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Bedrooms/Bunk%20Room.png','https://blueprince.wiki.gg/wiki/Bunk_Room',now()),
('Her Ladyship''s Chamber',53,'Her Ladyship''s Chamber','Her Ladyship''s Chamber','Tucked quietly away in the west wing of Mount Holly is the decorative bedroom of your grandmother, Lady Epsen. The style you find, unique in the house, a fitting tribute to her childhood home in Eraja.','Escondido discretamente na ala oeste de Mount Holly está o decorado quarto de sua avó, Lady Epsen. O estilo que você encontra, único na casa, é um tributo adequado à casa de sua infância em Eraja.','Rare','Raro','None (no gem cost)','Nenhum (sem custo em gemas)','Bedroom, Dead End','Quarto (Bedroom), Beco sem saída (Dead End)',ARRAY['Bedroom']::text[],'Bedrooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Bedrooms/Her%20Ladyship''s%20Chamber.png','https://blueprince.wiki.gg/wiki/Her_Ladyship''s_Chamber',now()),
('Master Bedroom',54,'Master Bedroom','Master Bedroom','H. S. Sinclair''s own room. Though perhaps soon you may consider it your own.','O próprio quarto de H. S. Sinclair. Embora talvez em breve você possa considerá-lo seu.','Rare','Raro','2 gems','2 gemas','Bedroom, Dead End','Quarto (Bedroom), Beco sem saída (Dead End)',ARRAY['Bedroom']::text[],'Bedrooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Bedrooms/Master%20Bedroom.png','https://blueprince.wiki.gg/wiki/Master_Bedroom',now()),
('Hallway',55,'Hallway','Hallway','One of the many nondescript hallways snaking through the estate and providing elegant causeways between the more noteworthy destinations that the house has to offer.','Um dos muitos corredores comuns que serpenteiam pela propriedade, oferecendo elegantes passagens entre os destinos mais notáveis que a casa tem a oferecer.','Commonplace','Comum','None (no gem cost)','Nenhum (sem custo em gemas)','Hallway','Corredor (Hallway)',ARRAY['Hallway']::text[],'Hallways','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Hallways/Hallway.png','https://blueprince.wiki.gg/wiki/Hallway',now()),
('West Wing Hall',56,'West Wing Hall','West Wing Hall','The west wing of the estate has been closed since the death of Lady Epsen. It is unsurprising therefore, that this hallway in its neglected state features boarded windows and dust smothered furniture.','A ala oeste da propriedade está fechada desde a morte de Lady Epsen. Não é de surpreender, portanto, que este corredor, em seu estado de abandono, apresente janelas tapadas e móveis cobertos de poeira.','Standard','Padrão','None (no gem cost)','Nenhum (sem custo em gemas)','Hallway','Corredor (Hallway)',ARRAY['Hallway']::text[],'Hallways','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Hallways/West%20Wing%20Hall.png','https://blueprince.wiki.gg/wiki/West_Wing_Hall',now()) on conflict (nome) do update set num=excluded.num,nome_en=excluded.nome_en,nome_pt=excluded.nome_pt,descricao_en=excluded.descricao_en,descricao_pt=excluded.descricao_pt,raridade_en=excluded.raridade_en,raridade_pt=excluded.raridade_pt,custo_en=excluded.custo_en,custo_pt=excluded.custo_pt,tipo_en=excluded.tipo_en,tipo_pt=excluded.tipo_pt,categorias=excluded.categorias,diretorio=excluded.diretorio,imagem=excluded.imagem,fonte=excluded.fonte,atualizado_em=excluded.atualizado_em;
